/*
 * JS for web/pages/admin.php's EditList::setHelp() help-popup feature
 * (currently used by web/pages/admintasks/serversettings.php).
 *
 * Extracted from an inline PHP-generated <script> block (GitHub issue #45).
 *
 * showHelp()/hideHelp() are declared on the global scope on purpose: the
 * markup generated by EditList::drawfields() still invokes them via inline
 * onmouseover="javascript:showHelp('...')" / onmouseout="javascript:hideHelp()"
 * attributes, so they must stay callable by name.
 */
(function() {
	const dataEl = document.getElementById('admin-help-data');
	if (!dataEl) {
		return;
	}

	const data = JSON.parse(dataEl.textContent);
	const texts = data.texts || {};
	const divId = data.div;

	window.showHelp = function(keyname) {
		const target = document.getElementById(divId);
		if (!target) {
			return;
		}
		target.innerHTML = texts[keyname];
		target.style.visibility = 'visible';
	};

	window.hideHelp = function() {
		const target = document.getElementById(divId);
		if (!target) {
			return;
		}
		target.style.visibility = 'hidden';
	};
})();
